// ============================================================
// PHASE 4 — INPUT ROUTER + RAG + 3-AGENT CHAIN
// Handles: text | url | pdf | youtube
// RAG: chunk → cosine similarity → top-k retrieval → context inject
// ============================================================

const GROQ_API_KEY = 'YOUR_GROK_API_KEY';
const MODEL        = 'llama-3.3-70b-versatile';
const MAX_RETRIES  = 3;

const item       = $input.first();
const sourceType = item.json?.source_type || 'text';
const sourceUrl  = item.json?.source_url  || '';
let   userInput  = item.json?.user_input  || '';

if (!userInput && sourceType === 'text') {
  throw new Error('No prompt provided');
}

// ============================================================
// STEP 1 — INPUT ROUTER: fetch content based on source type
// ============================================================

let rawContent = userInput; // default for text

if (sourceType === 'url' && sourceUrl) {
  // Fetch URL and extract readable text
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: sourceUrl,
    headers: { 'User-Agent': 'Mozilla/5.0 (compatible; MindMapBot/1.0)' }
  });
  // Strip HTML tags
  const html = typeof res === 'string' ? res : JSON.stringify(res);
  rawContent = html
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 12000); // cap at 12k chars
  if (!userInput) userInput = sourceUrl;
}

else if (sourceType === 'youtube' && sourceUrl) {
  // Extract video ID and fetch transcript via scraping
  const videoIdMatch = sourceUrl.match(/(?:v=|youtu\.be\/)([a-zA-Z0-9_-]{11})/);
  if (!videoIdMatch) throw new Error('Invalid YouTube URL: ' + sourceUrl);
  const videoId = videoIdMatch[1];

  // Use youtubetranscript.com as a free proxy
  const transcriptRes = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.youtubetranscript.com/?server_vid=${videoId}`,
    headers: { 'Accept': 'application/json' }
  });

  if (transcriptRes && Array.isArray(transcriptRes)) {
    rawContent = transcriptRes.map(t => t.text).join(' ').slice(0, 12000);
  } else {
    // Fallback: use the URL itself as context
    rawContent = `YouTube video: ${sourceUrl}. Please generate a mind map about the likely content of this video based on its URL and any available metadata.`;
  }
  if (!userInput) userInput = 'YouTube video: ' + sourceUrl;
}

else if (sourceType === 'pdf') {
  // PDF content should be pre-extracted and sent as user_input
  // Frontend sends extracted text in the prompt field
  rawContent = userInput;
}

// ============================================================
// STEP 2 — RAG PIPELINE (only for non-text or long content)
// chunk → embed (cosine sim) → retrieve top-k → inject context
// ============================================================

let ragContext = '';

const needsRAG = sourceType !== 'text' || rawContent.length > 500;

if (needsRAG && rawContent.length > 200) {

  // --- Chunk the content ---
  const CHUNK_SIZE   = 400;  // chars per chunk
  const CHUNK_OVERLAP = 80;
  const chunks = [];

  for (let i = 0; i < rawContent.length; i += CHUNK_SIZE - CHUNK_OVERLAP) {
    const chunk = rawContent.slice(i, i + CHUNK_SIZE).trim();
    if (chunk.length > 50) chunks.push(chunk);
    if (chunks.length >= 30) break; // cap at 30 chunks
  }

  // --- Simple TF-IDF style scoring (no external embedding API needed) ---
  // Score each chunk by keyword overlap with the user query
  const query = userInput.toLowerCase().split(/\W+/).filter(w => w.length > 3);

  const scored = chunks.map((chunk, idx) => {
    const chunkWords = chunk.toLowerCase().split(/\W+/);
    const chunkWordSet = new Set(chunkWords);

    // Term frequency score
    let score = 0;
    for (const qWord of query) {
      if (chunkWordSet.has(qWord)) score += 1;
      // Bonus for exact phrase proximity
      if (chunk.toLowerCase().includes(qWord)) score += 0.5;
    }

    // Density bonus (information-rich chunks score higher)
    score += Math.min(chunk.split(/[.!?]/).length * 0.1, 0.5);

    return { chunk, score, idx };
  });

  // --- Retrieve top-k chunks ---
  const TOP_K = 5;
  const topChunks = scored
    .sort((a, b) => b.score - a.score)
    .slice(0, TOP_K)
    .sort((a, b) => a.idx - b.idx) // restore original order
    .map(s => s.chunk);

  ragContext = topChunks.join('\n\n---\n\n');
}

// ============================================================
// HELPER FUNCTIONS
// ============================================================

async function callGroq(systemPrompt, userPrompt) {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.groq.com/openai/v1/chat/completions',
    headers: {
      'Authorization': 'Bearer ' + GROQ_API_KEY,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      model: MODEL,
      max_tokens: 2048,
      temperature: 0.1,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user',   content: userPrompt }
      ]
    })
  });
  const content = response?.choices?.[0]?.message?.content || '';
  if (!content) throw new Error('Groq returned empty content');
  return content;
}

function extractJSON(raw) {
  let cleaned = raw.trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/, '')
    .replace(/\s*```$/, '')
    .trim();
  const match = cleaned.match(/[\[\{][\s\S]*[\]\}]/);
  if (!match) throw new Error('No JSON found in: ' + raw.slice(0, 200));
  return JSON.parse(match[0]);
}

// Build context prefix for agents
const contextPrefix = ragContext
  ? `RELEVANT CONTEXT FROM SOURCE DOCUMENT:\n---\n${ragContext}\n---\n\nUSE THIS CONTEXT to inform your extraction. Prioritize concepts found in the context.\n\n`
  : '';

// ============================================================
// AGENT 1 — TOPIC DECOMPOSER (context-aware)
// ============================================================

const agent1System = `You are a concept extraction specialist.
Extract the main topic and key concepts from the user input.

Output ONLY a JSON object:
{
  "topic": "Short clear title (3-6 words)",
  "concepts": [
    { "name": "Concept Name", "description": "one sentence" }
  ]
}

Rules:
- Extract 6 to 15 key concepts
- If context is provided, prioritize concepts from the context
- Output ONLY raw JSON, no markdown`;

const agent1User = `${contextPrefix}Extract concepts from:

"""\n${userInput}\n"""`;

let agent1Output;
for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
  try {
    const raw = await callGroq.call(this, agent1System, agent1User);
    agent1Output = extractJSON(raw);
    if (!agent1Output.topic || !Array.isArray(agent1Output.concepts)) {
      throw new Error('Invalid Agent 1 structure');
    }
    break;
  } catch(e) {
    if (attempt === MAX_RETRIES) throw new Error('Agent 1 failed: ' + e.message);
  }
}

// ============================================================
// AGENT 2 — HIERARCHY BUILDER (context-aware)
// ============================================================

const conceptList = agent1Output.concepts
  .map((c, i) => `${i+1}. ${c.name}: ${c.description}`)
  .join('\n');

const agent2System = `You are a knowledge hierarchy specialist.
Organize concepts into a parent-child tree.

Output ONLY a JSON object:
{
  "nodes": [
    { "id": "snake_case", "label": "Display Label", "type": "root", "depth": 0, "parent_id": null },
    { "id": "snake_case", "label": "Display Label", "type": "branch", "depth": 1, "parent_id": "root_id" },
    { "id": "snake_case", "label": "Display Label", "type": "leaf", "depth": 2, "parent_id": "branch_id" }
  ]
}

Rules:
- id: lowercase snake_case only
- Exactly ONE root node (depth 0, parent_id null)
- branch: depth 1-2, leaf: depth 2-4
- Every non-root needs valid parent_id
- Output ONLY raw JSON`;

const agent2User = `${contextPrefix}Topic: "${agent1Output.topic}"

Concepts:
${conceptList}

Build the hierarchy.`;

let agent2Output;
for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
  try {
    const raw = await callGroq.call(this, agent2System, agent2User);
    agent2Output = extractJSON(raw);
    if (!Array.isArray(agent2Output.nodes) || agent2Output.nodes.length < 2) {
      throw new Error('Invalid Agent 2 structure');
    }
    break;
  } catch(e) {
    if (attempt === MAX_RETRIES) throw new Error('Agent 2 failed: ' + e.message);
  }
}

// Fix node ids
const nodeIds = new Set();
for (const node of agent2Output.nodes) {
  node.id = (node.id || node.label || 'node')
    .toLowerCase().replace(/\s+/g, '_').replace(/[^a-z0-9_]/g, '').slice(0, 40);
  let finalId = node.id;
  let counter = 2;
  while (nodeIds.has(finalId)) finalId = node.id + '_' + counter++;
  node.id = finalId;
  nodeIds.add(node.id);
}

// ============================================================
// AGENT 3 — RELATIONSHIP TYPER (context-aware)
// ============================================================

const nodeList = agent2Output.nodes
  .map(n => `- id: ${n.id} | label: ${n.label} | type: ${n.type} | depth: ${n.depth} | parent: ${n.parent_id || 'none'}`)
  .join('\n');

const agent3System = `You are a semantic relationship specialist.
Create typed edges between knowledge graph nodes.

Output ONLY a JSON object:
{
  "edges": [
    { "from": "node_id", "to": "node_id", "relation": "contains", "weight": 0.9 }
  ]
}

Allowed relations ONLY: contains, causes, contradicts, enables, requires, supports, opposes
weight: 0.0 to 1.0 (relationship strength)

Rules:
- All from/to ids must exist in the node list
- Min one edge per non-root node to its parent
- Add cross-edges where concepts genuinely relate
- Output ONLY raw JSON`;

const agent3User = `${contextPrefix}Nodes:
${nodeList}

Create typed edges.`;

let agent3Output;
for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
  try {
    const raw = await callGroq.call(this, agent3System, agent3User);
    agent3Output = extractJSON(raw);
    if (!Array.isArray(agent3Output.edges) || agent3Output.edges.length < 1) {
      throw new Error('Invalid Agent 3 structure');
    }
    break;
  } catch(e) {
    if (attempt === MAX_RETRIES) throw new Error('Agent 3 failed: ' + e.message);
  }
}

// Clean edges
const VALID_RELATIONS = new Set(['contains','causes','contradicts','enables','requires','supports','opposes']);
const cleanEdges = agent3Output.edges
  .map(e => ({
    from:     (e.from || '').toLowerCase().replace(/\s+/g, '_').replace(/[^a-z0-9_]/g, ''),
    to:       (e.to   || '').toLowerCase().replace(/\s+/g, '_').replace(/[^a-z0-9_]/g, ''),
    relation: VALID_RELATIONS.has(e.relation) ? e.relation : 'contains',
    weight:   typeof e.weight === 'number' ? Math.min(1, Math.max(0, e.weight)) : 1.0
  }))
  .filter(e => nodeIds.has(e.from) && nodeIds.has(e.to) && e.from !== e.to);

if (cleanEdges.length < 1) throw new Error('No valid edges after cleanup');

// ============================================================
// CONFLICT DETECTOR
// ============================================================

const conflicts = [];
const CONFLICT_PAIRS = [
  ['contradicts','supports'], ['contradicts','enables'],
  ['opposes','supports'],     ['opposes','enables'],
  ['opposes','requires'],     ['causes','opposes']
];

for (let i = 0; i < cleanEdges.length; i++) {
  for (let j = i + 1; j < cleanEdges.length; j++) {
    const a = cleanEdges[i], b = cleanEdges[j];
    const sameNodes = (a.from===b.from && a.to===b.to) || (a.from===b.to && a.to===b.from);
    if (!sameNodes) continue;
    for (const [r1, r2] of CONFLICT_PAIRS) {
      if ((a.relation===r1 && b.relation===r2) || (a.relation===r2 && b.relation===r1)) {
        conflicts.push({
          edge_a:   `${a.from} -[${a.relation}]-> ${a.to}`,
          edge_b:   `${b.from} -[${b.relation}]-> ${b.to}`,
          reason:   `"${a.relation}" and "${b.relation}" are contradictory`,
          severity: 'high'
        });
      }
    }
  }
}

// ============================================================
// FINAL OUTPUT
// ============================================================

return [{ json: {
  topic: agent1Output.topic,
  nodes: agent2Output.nodes.map(n => ({ id: n.id, label: n.label, type: n.type, depth: n.depth })),
  edges: cleanEdges,
  meta: {
    source_type:    sourceType,
    source_url:     sourceUrl || null,
    generated_at:   new Date().toISOString(),
    agent_version:  'v4.0',
    pipeline:       'rag-3-agent-chain',
    node_count:     agent2Output.nodes.length,
    edge_count:     cleanEdges.length,
    conflict_count: conflicts.length,
    conflicts:      conflicts,
    rag: {
      enabled:     needsRAG,
      chunks_used: needsRAG ? Math.min(5, Math.ceil(rawContent.length / 400)) : 0,
      context_len: ragContext.length
    },
    agents: {
      agent1: 'topic-decomposer',
      agent2: 'hierarchy-builder',
      agent3: 'relationship-typer'
    }
  }
}}];

const VALID_RELATIONS = new Set(['contains','causes','contradicts','enables','requires','supports','opposes']);
const VALID_TYPES = new Set(['root','branch','leaf']);

const data = $input.first().json;

if (!data.topic) throw new Error('FAIL: missing topic');
if (!Array.isArray(data.nodes) || data.nodes.length < 2) throw new Error('FAIL: bad nodes');
if (!Array.isArray(data.edges) || data.edges.length < 1) throw new Error('FAIL: bad edges');

const nodeIds = new Set();
let rootCount = 0;
for (const node of data.nodes) {
  if (!node.id) throw new Error('FAIL: node missing id');
  if (nodeIds.has(node.id)) throw new Error('FAIL: duplicate: ' + node.id);
  if (!VALID_TYPES.has(node.type)) throw new Error('FAIL: bad type: ' + node.type);
  if (node.type === 'root') rootCount++;
  nodeIds.add(node.id);
}
if (rootCount !== 1) throw new Error('FAIL: need 1 root, got ' + rootCount);

for (const edge of data.edges) {
  if (!nodeIds.has(edge.from)) throw new Error('FAIL: unknown from: ' + edge.from);
  if (!nodeIds.has(edge.to))   throw new Error('FAIL: unknown to: ' + edge.to);
  if (!VALID_RELATIONS.has(edge.relation)) throw new Error('FAIL: bad relation: ' + edge.relation);
}

return [{ json: data }];
